private static bool TryAcquireSingleInstanceMutex() {
    Mutex instance = new(false, ProgramGUID);
    bool acquired;
    try {
        acquired = instance.WaitOne(TimeSpan.Zero, true);
    }
    catch (AbandonedMutexException) {
        acquired = true;
        Log.Write("Recovered abandoned single-instance mutex from an abnormally terminated prior instance.");
    }

    if (!acquired) {
        instance.Dispose();
        return false;
    }

    Instance = instance;
    return true;
}

